#!/usr/bin/env python3
"""Build an offline index from public glyph IDs and component references."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
manifest=json.loads((ROOT/'ebag/manifest.json').read_text())
data=[[r['id'],r['codepoint'],' '.join(r['components'])] for r in manifest['glyphs']]
page=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>OpenGlyph 隶定字索引</title><style>
@font-face{font-family:Ebag;src:url(ebag/OpenGlyphEbag.otf) format('opentype');font-display:block}*{box-sizing:border-box}body{margin:0;background:#f3f1eb;color:#253b32;font:16px/1.7 -apple-system,BlinkMacSystemFont,'PingFang SC',sans-serif}main{max-width:1100px;padding:28px 18px;margin:auto}h1{font-size:30px;margin-bottom:8px}p{color:#5e7167}.toolbar{position:sticky;top:0;background:#f3f1eb;padding:12px 0;z-index:1}input{width:100%;padding:14px;border:1px solid #b8c5b9;border-radius:9px;font-size:17px}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}article{background:white;border:1px solid #dce2d9;border-radius:12px;padding:12px;text-align:center}.glyph{font-family:Ebag;font-size:90px;line-height:1.3;font-synthesis:none;display:block}.id{font:13px monospace}button{border:0;background:#e5eee2;color:#31583c;padding:7px 12px;border-radius:7px;cursor:pointer}article button{margin-top:10px;width:100%}a{color:#356d4b;font-size:12px}.pagination{display:flex;gap:12px;align-items:center;justify-content:center;margin:20px 0}#status{font-size:13px}.help{font-size:13px}#command{font:15px/1.8 monospace;background:#fff;padding:10px;border-radius:6px;white-space:pre-wrap;overflow-wrap:anywhere}#copy-status{font-size:12px;color:#35704e}footer{font-size:12px;color:#778276;margin:30px 0}
</style><main><h1>22,583 个已有隶定字，按编号排进论文。</h1><p>这是本地字体索引，不是图片拼贴。字形来自 GlyphWiki ebag_s；选字仍须与文献原形核对。</p><div class="toolbar"><input id="query" aria-label="按编号或部件搜索" placeholder="输入 s030-067、u81e3，或一个普通汉字作为部件线索"><div id="status"></div></div><p class="help">直接输入汉字时，查的是部件编号，不代表命中结果就是该字。没有释读信息的形不自动补读音。点击按钮得到可复制的 LaTeX 命令。</p><pre id="command">\ebag{s030-067}</pre><span id="copy-status"></span><div id="grid"></div><div class="pagination"><button id="prev">上一页</button><span id="page"></span><button id="next">下一页</button></div><footer>OpenGlyph-LaTeX v0.1.0 · 字体局部 PUA 不是标准 Unicode 身份 · 许可与来源见 THIRD-PARTY-NOTICES.md</footer></main><script>
const all=DATA,query=document.getElementById('query'),grid=document.getElementById('grid');let page=0,filtered=all;const size=60;
function filter(){let q=query.value.trim().toLowerCase().replace(/^ebag[:_]/,'');if(Array.from(q).length===1&&q.codePointAt(0)>127)q='u'+q.codePointAt(0).toString(16);filtered=all.filter(r=>r[0].includes(q)||r[2].includes(q));page=0;render();}
function render(){grid.replaceChildren();const start=page*size;for(const r of filtered.slice(start,start+size)){const card=document.createElement('article'),glyph=document.createElement('span'),id=document.createElement('div'),button=document.createElement('button'),link=document.createElement('a');glyph.className='glyph';glyph.textContent=String.fromCodePoint(r[1]);id.className='id';id.textContent=r[0];button.textContent='复制 LaTeX';button.onclick=async()=>{const text='\\ebag{'+r[0]+'}';document.getElementById('command').textContent=text;try{await navigator.clipboard.writeText(text);document.getElementById('copy-status').textContent='已复制';}catch{document.getElementById('copy-status').textContent='浏览器限制自动复制，请选中上方命令手动复制。';}};link.textContent='查看 GlyphWiki 来源';link.href='https://glyphwiki.org/wiki/ebag_'+r[0];link.target='_blank';link.rel='noopener noreferrer';card.append(glyph,id,button,link);grid.append(card);}document.getElementById('status').textContent=filtered.length+' 项结果 / 全库 '+all.length+' 项';document.getElementById('page').textContent=(filtered.length?page+1:0)+' / '+Math.ceil(filtered.length/size);document.getElementById('prev').disabled=page===0;document.getElementById('next').disabled=start+size>=filtered.length;}
query.oninput=filter;document.getElementById('prev').onclick=()=>{if(page>0){page--;render();}};document.getElementById('next').onclick=()=>{if((page+1)*size<filtered.length){page++;render();}};filter();
</script></html>'''
(ROOT/'字形索引.html').write_text(page.replace('DATA',json.dumps(data,ensure_ascii=True,separators=(',',':'))),encoding='utf-8')
print(json.dumps(dict(entries=len(data),bytes=(ROOT/'字形索引.html').stat().st_size)))
